    class NumberSystemSolver
    {
        public static int FindBase(int A, int B, int D, int E)
        {
            // Single loop for B to D-1
            for (int b = 2; b < D; b++)
            {
                string result = Convert((A * b + B * b + C * b + D * b) % b, b);
                if (Convert(E, b) == result)
                {
                    return b;
                }
            }
            return 0;
        }

        // Helper function to convert a number from base to decimal
        private static string Convert(int num, int b)
        {
            return num.ToString().PadLeft(num.ToString().Length, '0');
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            Console.Write("Enter A: ");
            int A = int.Parse(Console.ReadLine());
            Console.Write("Enter B: ");
            int B = int.Parse(Console.ReadLine());
            Console.Write("Enter C: ");
            int C = int.Parse(Console.ReadLine());
            Console.Write("Enter D: ");
            int D = int.Parse(Console.ReadLine());
            Console.Write("Enter E: ");
            int E = int.Parse(Console.ReadLine());

            int baseOfNumberSystem = NumberSystemSolver.FindBase(A, B, D, E);
            if (baseOfNumberSystem > 0)
            {
                Console.WriteLine($"A = {A}, B = {B}, C = {C}, D = {D}, E = {E} are in base {baseOfNumberSystem}.");
            }
            else
